    "image": "",
    "isNutFree": true,
    "isGlutenFree": true,
    "isDairyFree": true,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": true,
    "isPescatarian": true,
    "isCandidaFriendly": true,
