    "image": "",
    "isNutFree": true,
    "isGlutenFree": true,
    "isDairyFree": true,
    "isEggFree": false,
    "isVegetarian": false,
    "isVegan": false,
    "isPescatarian": false,
    "isCandidaFriendly": true,
